import { blocks, type Resume } from './model';
export const escapeTex = (s: string) =>
  s
    .replace(
      /[\\{}$&%#_^~]/g,
      (c) =>
        ({
          '\\': '\\textbackslash{}',
          '{': '\\{',
          '}': '\\}',
          $: '\\$',
          '&': '\\&',
          '%': '\\%',
          '#': '\\#',
          _: '\\_',
          '^': '\\textasciicircum{}',
          '~': '\\textasciitilde{}',
        })[c]!,
    )
    .replace(/\r?\n/g, ' ');
const PREAMBLE = (r: Resume) =>
  [
    '% Generated by Folio. Compile with pdfLaTeX (e.g. in Overleaf).',
    '% Single-column, text-based resume. Review content and pagination before applying.',
    `\\documentclass[11pt,${r.paper === 'A4' ? 'a4paper' : 'letterpaper'}]{article}`,
    '\\usepackage[margin=0.7in]{geometry}',
    '\\usepackage[T1]{fontenc}',
    '\\usepackage[utf8]{inputenc}',
    '\\usepackage{lmodern}',
    '\\renewcommand{\\familydefault}{\\sfdefault}',
    '\\pagestyle{empty}',
    '\\setlength{\\parindent}{0pt}',
    '\\setlength{\\parskip}{5pt}',
    '\\begin{document}',
  ].join('\n');

export function makeTex(r: Resume) {
  const out: string[] = [];
  let inList = false;
  const closeList = () => {
    if (inList) out.push('\\end{itemize}}');
    inList = false;
  };
  for (const b of blocks(r)) {
    const t = escapeTex(b.text);
    if (b.kind === 'bullet') {
      if (!inList)
        out.push(
          '{\\setlength{\\parskip}{0pt}',
          '\\begin{itemize}',
          '\\setlength{\\itemsep}{0pt}',
          '\\setlength{\\topsep}{0pt}',
        );
      inList = true;
      // \item{} so a bullet starting with "[" is not read as the optional label.
      out.push(`\\item{} ${t}`);
      continue;
    }
    closeList();
    switch (b.kind) {
      case 'name':
        out.push(`{\\LARGE\\bfseries ${t}}\\par`);
        break;
      case 'heading':
        out.push(`\\par\\medskip{\\large\\bfseries ${t}}\\par\\nopagebreak`);
        break;
      case 'role':
        out.push(`\\textbf{${t}}\\par\\nopagebreak`);
        break;
      default:
        out.push(`${t}\\par`);
    }
  }
  closeList();
  return `${PREAMBLE(r)}\n${out.join('\n')}\n\\end{document}\n`;
}
